      postJson<{ crews: Crew[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/crews/members`, f),
    onSuccess: async () => {
      setMember('');
      // A crew is also a pool of its name: its pool (and every pool's cuts) follow it.
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: crewsKey(sheetId) }),
        queryClient.invalidateQueries({ queryKey: poolsKey(sheetId) }),
      ]);
    },
  });

  return (
    <div data-testid={`crew-row-${crew.name}`}>
      <strong data-testid="crew-name">{crew.name}</strong>{' '}
      Lead <span data-testid="crew-lead">{crew.lead}</span>{' '}
      Due-total <span data-testid="crew-due-total">{fig(due)}</span>
      <ul>
        {crew.members.map((m) => (
          <li key={m.personId} data-testid="crew-member-line">
            <span data-testid="crew-member-name">{m.name}</span>
          </li>
        ))}
      </ul>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          submitOnce(() => {
            add.reset();
            return add.mutateAsync({ crew: crew.name, personId: member === '' ? null : Number(member) });
          });
        }}
      >
        <select
          data-testid="crew-member-select"
          value={member}
          onChange={(e: ChangeEvent<HTMLSelectElement>) => {
            setMember(e.target.value);
            add.reset();
          }}
        >
          <option value="">Choose a person</option>
          {people.map((p) => (
            <option key={p.id} value={String(p.id)}>
              {p.name}
            </option>
          ))}
        </select>{' '}
        <button type="submit" data-testid="crew-member-add" disabled={add.isPending}>
          Add member
        </button>
      </form>
      {add.isError && <p data-testid="crew-error">{add.error.message}</p>}
    </div>
  );
}

/** The sheet's crews: a form that adds one (a name, unique on the sheet, and a lead) and each crew with its members. */
function Crews({ sheetId }: { sheetId: string }) {
  const crews = useCrews(sheetId);
  const people = usePeople(sheetId);
  const queryClient = useQueryClient();
  const [name, setName] = useState('');
  const [lead, setLead] = useState('');

  const submitOnce = useSingleFlight();
  const save = useMutation({
    mutationFn: (f: { name: string; leadId: number | null }) =>
      postJson<{ crews: Crew[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/crews`, f),
    onSuccess: async () => {
      setName('');
      setLead('');
      // A crew is also a pool of its name: its pool (and every pool's cuts) follow it.
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: crewsKey(sheetId) }),
        queryClient.invalidateQueries({ queryKey: poolsKey(sheetId) }),
      ]);
    },
  });

  return (
    <section data-testid="crews">
      <form
        data-testid="crew-form"
        onSubmit={(e) => {
          e.preventDefault();
          submitOnce(() => {
            save.reset();
            return save.mutateAsync({ name, leadId: lead === '' ? null : Number(lead) });
          });
        }}
      >
        <label>
          Crew{' '}
          <input
            data-testid="crew-form-name"
            value={name}
            onChange={(e) => {
              setName(e.target.value);
              save.reset();
            }}
          />
        </label>{' '}
        <label>
          Lead{' '}
          <select
            data-testid="crew-form-lead"
            value={lead}
            onChange={(e: ChangeEvent<HTMLSelectElement>) => {
              setLead(e.target.value);
              save.reset();
            }}
          >
            <option value="">Choose a person</option>
            {(people.data ?? []).map((p) => (
              <option key={p.id} value={String(p.id)}>
                {p.name}
              </option>
            ))}
          </select>
        </label>{' '}
        <button type="submit" data-testid="crew-form-submit" disabled={save.isPending}>
          Add crew
        </button>
        {save.isError && <p data-testid="crew-form-error">{save.error.message}</p>}
      </form>
      {(crews.data ?? []).map((c) => (
        <CrewRow key={c.name} sheetId={sheetId} crew={c} people={people.data ?? []} />
      ))}
      {crews.isError && <p data-testid="crews-error">{crews.error.message}</p>}
    </section>
  );
}

export const contribution = SheetBody.fill({ order: 7.5, Component: ({ sheetId }) => <Crews sheetId={sheetId} /> });
import { useEffect, useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { SheetBody } from '../../slots/defs/sheetBody';
import { useClaims } from '../claims/useClaims';
import { useAliases, usePeople } from '../people/usePeople';
import { useDueTotals } from '../rates/useDueTotals';
import { useRates } from '../rates/useRates';
import { useSettings } from '../settings/useSettings';
import { useSheetToday } from '../today/useSheetToday';

/** One search: its text, and the sheets it runs over (this sheet first, then the others of its tree by id). */
type Run = { n: number; text: string; sheets: string[] };

/** Works out one sheet's matching lines (`<sheet id> <name> <due-total>`, in list order, retired people
 *  included) with the same hooks its own screen uses, and hands them up once all is read; shows nothing. */
function SheetMatches({ sheetId, text, onLines }: { sheetId: string; text: string; onLines: (id: string, lines: string[]) => void }) {
  const people = usePeople(sheetId);
  const aliases = useAliases(sheetId);
  const ready = [people, aliases, useClaims(sheetId), useRates(sheetId), useSheetToday(sheetId), useSettings(sheetId)]
    .every((q) => q.isSuccess);
  const due = useDueTotals(sheetId);
  const wanted = text.trim().toLowerCase();
  const lines = (people.data ?? [])
    .filter((p) => [p.name, ...(aliases.data ?? []).filter((a) => a.personId === p.id).map((a) => a.alias)]
      .some((n) => n.toLowerCase().includes(wanted)))
    .map((p) => `${sheetId} ${p.name} ${due.get(p.id) ?? 'n/a'}`);
  const joined = lines.join('\n');
  useEffect(() => {
    if (ready) onLines(sheetId, joined === '' ? [] : joined.split('\n'));
  }, [ready, sheetId, joined, onLines]);
  return null;
}

/** A search box and button listing, over this sheet and every other sheet of its tree, every person whose name or
 *  an alias contains the typed text (case ignored): one line per person, `<sheet id> <name> <due-total>`, this
 *  sheet's people first in list order, then the other sheets' by sheet id. The other sheets are re-read from the
 *  store on each press; the count is cleared while a search runs. */
function TreeSearch({ sheetId }: { sheetId: string }) {
  const queryClient = useQueryClient();
  const [text, setText] = useState('');
  const [run, setRun] = useState<Run | null>(null);
  const [found, setFound] = useState<{ n: number; lines: Record<string, string[]> }>({ n: 0, lines: {} });
  const [counter, setCounter] = useState(0);
  const [onLines] = useState(() => (id: string, lines: string[]) =>
    setFound((f) => ({ ...f, lines: { ...f.lines, [id]: lines } })));

  const search = async () => {
    const n = counter + 1;
    setCounter(n);
    setRun(null);
    setFound({ n, lines: {} });
    const { sheets } = await getJson<{ sheets: string[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/tree`);
    for (const id of sheets) queryClient.removeQueries({ queryKey: ['sheet', id] });
    setRun({ n, text, sheets: [sheetId, ...sheets] });
  };

  const done = run !== null && found.n === run.n && run.sheets.every((id) => found.lines[id] !== undefined);
  const lines = done ? run.sheets.flatMap((id) => found.lines[id]) : [];

  return (
    <section>
      <input
        type="text"
        placeholder="Search the tree"
        data-testid="search-name"
        value={text}
        onChange={(e) => setText(e.target.value)}
      />{' '}
      <button type="button" data-testid="search" onClick={() => void search()}>
        Search
      </button>{' '}
      <span data-testid="search-count">{done ? lines.length : ''}</span>
      {run?.sheets.map((id) => (
        <SheetMatches key={`${run.n}-${id}`} sheetId={id} text={run.text} onLines={onLines} />
      ))}
      <ul>
        {lines.map((line, i) => (
          <li key={i} data-testid="search-line">
            {line}
          </li>
        ))}
      </ul>
    </section>
  );
}

export const contribution = SheetBody.fill({ order: 9, Component: ({ sheetId }) => <TreeSearch sheetId={sheetId} /> });
import { useQuery } from '@tanstack/react-query';
import { useReader } from '../../api/readNow';

export type SheetToday = { id: string; today: string; archived: boolean };

/** The sheet's today (yyyy-mm-dd), and whether it is archived. Every date decision and default date in a sheet uses this,
 *  never the browser's clock. */
export function useSheetToday(sheetId: string) {
  const read = useReader();
  return useQuery({
    queryKey: read.key(['sheet', sheetId, 'today']),
    queryFn: () => read.get<SheetToday>(`/api/sheets/${encodeURIComponent(sheetId)}/today`),
  });
}

